'use client'

import { useEffect, useRef, useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { Navbar } from '@/components/navbar'
import { Footer } from '@/components/footer'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Badge } from '@/components/ui/badge'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { 
  getCurrentUser, 
  addReport, 
  generateCaseId,
  addEvidence,
  getUserById,
} from '@/lib/mock-data'
import { MessageCircle, Send, Upload, Moon, Sun, AlertCircle, FileText, CheckCircle, Loader } from 'lucide-react'

type ChatStep = 'welcome' | 'safety-check' | 'incident-type' | 'platform' | 'details' | 'evidence' | 'review' | 'submitted'

interface ChatMessage {
  id: string
  type: 'bot' | 'user'
  content: string
  timestamp: Date
  isQuickReply?: boolean
}

export default function ChatbotPage() {
  const [step, setStep] = useState<ChatStep>('welcome')
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [isDarkMode, setIsDarkMode] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [caseId, setCaseId] = useState<string | null>(null)

  // Form state
  const [reporterName, setReporterName] = useState('')
  const [userMessage, setUserMessage] = useState('')
  const [incidentType, setIncidentType] = useState('')
  const [platform, setPlatform] = useState('')
  const [description, setDescription] = useState('')
  const [uploadedFiles, setUploadedFiles] = useState<File[]>([])
  const [isGuest, setIsGuest] = useState(false)
  const [reportedAt, setReportedAt] = useState(new Date())

  const messagesEndRef = useRef<HTMLDivElement>(null)
  const router = useRouter()

  useEffect(() => {
    const currentUser = getCurrentUser()
    if (currentUser) {
      setIsGuest(false)
    } else {
      setIsGuest(true)
      setReporterName('Guest Reporter')
    }

    // Add welcome message
    const welcomeMsg: ChatMessage = {
      id: '1',
      type: 'bot',
      content: `Welcome to TrustLine Support. I'm here to help you report cyberbullying, online harassment, or privacy violations. Everything you share is confidential and secure. How are you feeling right now?`,
      timestamp: new Date(),
      isQuickReply: true,
    }
    setMessages([welcomeMsg])
  }, [])

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const addMessage = (type: 'bot' | 'user', content: string, isQuickReply = false) => {
    const newMsg: ChatMessage = {
      id: Date.now().toString(),
      type,
      content,
      timestamp: new Date(),
      isQuickReply,
    }
    setMessages(prev => [...prev, newMsg])
  }

  const handleQuickReply = (reply: string) => {
    addMessage('user', reply)

    if (step === 'welcome') {
      addMessage('bot', 'Thank you for reaching out. Let\'s get started with gathering some information.')
      setTimeout(() => {
        addMessage('bot', 'What type of incident are you reporting?', true)
        setStep('incident-type')
      }, 500)
    } else if (step === 'safety-check') {
      if (reply.includes('concerned')) {
        addMessage('bot', 'Your safety is our priority. Please reach out to a trusted adult, school counselor, or call our support line at 1-800-TRUSTLINE. We\'re here to help.')
      }
      setTimeout(() => {
        addMessage('bot', 'Now, what platform did this happen on?', true)
        setStep('platform')
      }, 1000)
    } else if (step === 'incident-type') {
      setIncidentType(reply)
      addMessage('bot', 'Thank you. What platform did this happen on?', true)
      setStep('platform')
    } else if (step === 'platform') {
      setPlatform(reply)
      addMessage('bot', 'Now, please describe what happened. Include as much detail as you\'re comfortable sharing.')
      setStep('details')
    }
  }

  const handleSubmitDetails = (e: React.FormEvent) => {
    e.preventDefault()
    if (!description.trim()) return

    addMessage('user', description)
    setDescription('')
    addMessage('bot', 'Thank you for sharing. You can now upload evidence like screenshots, videos, or messages. This helps us investigate your case.')
    setTimeout(() => {
      addMessage('bot', 'Do you have any evidence to upload?', true)
      setStep('evidence')
    }, 500)
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.currentTarget.files
    if (!files) return

    const newFiles = Array.from(files)
    if (uploadedFiles.length + newFiles.length > 10) {
      addMessage('bot', 'You can upload a maximum of 10 files per report. Please remove some files first.')
      return
    }

    setUploadedFiles(prev => [...prev, ...newFiles])
    addMessage('user', `Uploaded ${newFiles.length} file(s)`)
  }

  const removeFile = (index: number) => {
    setUploadedFiles(prev => prev.filter((_, i) => i !== index))
  }

  const handleSubmitReport = async () => {
    if (!incidentType || !platform || !description) {
      addMessage('bot', 'Please provide all required information before submitting.')
      return
    }

    setIsLoading(true)
    addMessage('user', 'Submit my report')

    setTimeout(() => {
      setStep('review')
      addMessage('bot', 'Perfect! Let me review your report information...')

      setTimeout(() => {
        // Create the report
        const newCaseId = generateCaseId()
        setCaseId(newCaseId)

        const currentUser = getCurrentUser()
        const userId = currentUser?.userId || `guest-${Date.now()}`
        const reportData = {
          id: `report-${Date.now()}`,
          caseId: newCaseId,
          userId,
          reporterName: reporterName || 'Guest Reporter',
          incidentType,
          platform,
          description,
          status: 'pending' as const,
          priority: incidentType.includes('threat') || incidentType.includes('leak') ? 'high' : 'medium',
          evidence: [],
          createdAt: new Date().toISOString(),
          submittedAt: new Date().toISOString(),
          messages: [
            {
              id: 'initial-msg',
              sender: 'user' as const,
              senderName: reporterName || 'Guest',
              content: `Report submitted for ${incidentType} incident on ${platform}`,
              createdAt: new Date().toISOString(),
            }
          ],
          internalNotes: [],
        }

        addReport(reportData)
        setStep('submitted')
        addMessage('bot', `Excellent! Your report has been submitted successfully. Your Case ID is: **${newCaseId}**\n\nWe've assigned your case to a specialized reviewer who will investigate within 24 hours. You'll receive updates via secure messages in your account.\n\nThank you for helping us create a safer online community.`, false)

        setIsLoading(false)
      }, 1000)
    }, 800)
  }

  const getQuickReplies = (): string[] => {
    switch (step) {
      case 'welcome':
        return ['I\'m doing okay', 'I\'m very concerned', 'I need immediate help']
      case 'incident-type':
        return ['Cyberbullying', 'Online Harassment', 'Private Media Leak', 'Threatening Messages', 'Other']
      case 'platform':
        return ['Social Media', 'Email', 'Messaging App', 'Gaming Platform', 'Other Online Platform']
      case 'evidence':
        return ['Upload Evidence', 'Skip for Now', 'Ready to Submit']
      default:
        return []
    }
  }

  return (
    <>
      <Navbar />
      <main className="min-h-screen bg-gradient-to-b from-slate-50 to-slate-100 py-8">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 h-[calc(100vh-200px)] flex flex-col">
          {/* Header */}
          <div className="flex justify-between items-center mb-4">
            <div>
              <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-2">
                <MessageCircle className="w-8 h-8 text-cyan-600" />
                TrustLine Support Chat
              </h1>
              <p className="text-slate-600 text-sm">24/7 Support available • All conversations are encrypted</p>
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setIsDarkMode(!isDarkMode)}
              className="h-9 w-9"
            >
              {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
            </Button>
          </div>

          {/* Chat Container */}
          <Card className={`flex-1 flex flex-col mb-4 ${isDarkMode ? 'bg-slate-800 border-slate-700' : ''}`}>
            {/* Messages */}
            <CardContent className={`flex-1 overflow-y-auto p-6 space-y-4 ${isDarkMode ? 'bg-slate-800' : ''}`}>
              {messages.map((msg) => (
                <div key={msg.id} className={`flex ${msg.type === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div
                    className={`max-w-xs lg:max-w-md xl:max-w-lg px-4 py-3 rounded-lg ${
                      msg.type === 'user'
                        ? 'bg-cyan-600 text-white rounded-br-none'
                        : isDarkMode
                        ? 'bg-slate-700 text-white rounded-bl-none'
                        : 'bg-slate-100 text-slate-900 rounded-bl-none'
                    }`}
                  >
                    <p className="text-sm whitespace-pre-wrap break-words">{msg.content}</p>
                    <p className={`text-xs mt-1 ${msg.type === 'user' ? 'text-cyan-100' : 'text-slate-500'}`}>
                      {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </p>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </CardContent>

            {/* Quick Replies */}
            {getQuickReplies().length > 0 && step !== 'details' && step !== 'submitted' && (
              <div className={`px-6 py-4 border-t ${isDarkMode ? 'border-slate-700 bg-slate-750' : 'border-slate-200'}`}>
                <p className={`text-xs font-medium mb-3 ${isDarkMode ? 'text-slate-400' : 'text-slate-600'}`}>Quick replies:</p>
                <div className="flex flex-wrap gap-2">
                  {getQuickReplies().map((reply, idx) => (
                    <Button
                      key={idx}
                      variant="outline"
                      size="sm"
                      onClick={() => handleQuickReply(reply)}
                      disabled={isLoading}
                      className={isDarkMode ? 'border-slate-600 text-white hover:bg-slate-700' : ''}
                    >
                      {reply}
                    </Button>
                  ))}
                </div>
              </div>
            )}

            {/* Input Area */}
            {step === 'details' && (
              <form onSubmit={handleSubmitDetails} className={`border-t ${isDarkMode ? 'border-slate-700 bg-slate-750' : 'border-slate-200'} p-6 space-y-4`}>
                <Textarea
                  placeholder="Describe what happened in detail..."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  disabled={isLoading}
                  className={isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : ''}
                />
                <Button type="submit" disabled={isLoading || !description.trim()} className="w-full bg-cyan-600 hover:bg-cyan-700">
                  <Send className="w-4 h-4 mr-2" />
                  Continue
                </Button>
              </form>
            )}

            {/* Evidence Upload Area */}
            {step === 'evidence' && (
              <div className={`border-t ${isDarkMode ? 'border-slate-700 bg-slate-750' : 'border-slate-200'} p-6 space-y-4`}>
                <div>
                  <Label htmlFor="evidence" className={isDarkMode ? 'text-white' : ''}>
                    Upload Evidence
                  </Label>
                  <div className="mt-2 border-2 border-dashed border-slate-300 rounded-lg p-6 text-center cursor-pointer hover:border-cyan-400 transition-colors">
                    <input
                      id="evidence"
                      type="file"
                      multiple
                      onChange={handleFileUpload}
                      disabled={isLoading || uploadedFiles.length >= 10}
                      className="hidden"
                    />
                    <label htmlFor="evidence" className="cursor-pointer block">
                      <Upload className="w-8 h-8 mx-auto mb-2 text-slate-400" />
                      <p className={`text-sm font-medium ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Click to upload or drag and drop</p>
                      <p className="text-xs text-slate-500 mt-1">PNG, JPG, PDF, MP4, etc. Max 50MB each</p>
                    </label>
                  </div>
                </div>

                {uploadedFiles.length > 0 && (
                  <div className="space-y-2">
                    <p className="text-sm font-medium">Uploaded files:</p>
                    {uploadedFiles.map((file, idx) => (
                      <div key={idx} className={`flex items-center justify-between p-3 rounded border ${isDarkMode ? 'border-slate-600 bg-slate-700' : 'border-slate-200 bg-slate-50'}`}>
                        <div className="flex items-center gap-2">
                          <FileText className="w-4 h-4 text-cyan-600" />
                          <span className={`text-sm ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{file.name}</span>
                          <span className="text-xs text-slate-500">({(file.size / 1024 / 1024).toFixed(2)} MB)</span>
                        </div>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => removeFile(idx)}
                          className="h-6"
                        >
                          ✕
                        </Button>
                      </div>
                    ))}
                  </div>
                )}

                <div className="flex gap-3 pt-4">
                  <Button
                    onClick={handleSubmitReport}
                    disabled={isLoading}
                    className="flex-1 bg-cyan-600 hover:bg-cyan-700"
                  >
                    {isLoading ? <Loader className="w-4 h-4 mr-2 animate-spin" /> : <CheckCircle className="w-4 h-4 mr-2" />}
                    {isLoading ? 'Submitting...' : 'Submit Report'}
                  </Button>
                </div>
              </div>
            )}

            {/* Submitted State */}
            {step === 'submitted' && (
              <div className={`border-t ${isDarkMode ? 'border-slate-700 bg-slate-750' : 'border-slate-200'} p-6`}>
                {caseId && (
                  <div className="space-y-4">
                    <Card className="bg-green-50 border-green-200">
                      <CardContent className="pt-6">
                        <div className="flex gap-3">
                          <CheckCircle className="w-6 h-6 text-green-600 flex-shrink-0 mt-1" />
                          <div>
                            <p className="font-semibold text-green-900">Report Submitted Successfully</p>
                            <p className="text-sm text-green-800 mt-1">Case ID: <strong>{caseId}</strong></p>
                            <p className="text-sm text-green-700 mt-2">Save this case ID to track your report.</p>
                          </div>
                        </div>
                      </CardContent>
                    </Card>

                    <div className="flex flex-col sm:flex-row gap-3">
                      {!isGuest && (
                        <Button asChild className="flex-1 bg-cyan-600 hover:bg-cyan-700">
                          <Link href="/dashboard">View Dashboard</Link>
                        </Button>
                      )}
                      <Button
                        onClick={() => window.location.reload()}
                        variant="outline"
                        className="flex-1"
                      >
                        Start New Report
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </Card>

          {/* Footer Info */}
          <Alert className="bg-cyan-50 border-cyan-200">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="text-cyan-900">
              All reports are confidential. You can track your case status by logging in to your dashboard or using your Case ID.
            </AlertDescription>
          </Alert>
        </div>
      </main>
      <Footer />
    </>
  )
}
